-- The two checklists published on 2026-10-30: The First Weeks With a Newborn
-- (Newborn) and When Your Faith Feels Far Away (Faith).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-30`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-first-weeks-with-a-newborn', 'The First Weeks With a Newborn', 'For the first weeks with a newborn, when the days have no shape. It gets feeds and diapers on one sheet, puts visitors behind a rule, splits the night into named shifts, and keeps the parent''s own checkup on the calendar.', 'Newborn', '["Write feeds and diapers on one sheet — the pediatrician asks and nobody remembers.", "Let someone else cook one meal a day — food that arrives beats food you planned.", "Put visitors behind a clear rule — an hour, after two, and hands washed before holding.", "Split the night into shifts you name — four unbroken hours each beats eight broken ones.", "Get outside once, even to the mailbox — daylight and air do something no nap does.", "Keep your own checkup on the calendar — the parent''s appointment is the first one dropped.", "Expect the evening to be the hard part — the late fussing is normal and it passes.", "Send the small question to the pediatrician — the nurse line exists for exactly these.", "Call 1-833-TLC-MAMA if the dark stays — the maternal mental health line answers day and night."]'::jsonb, 'daily', array['Parenting', 'Self-Care']::text[], 1, '2026-10-30T16:00:00+00:00'::timestamptz),
  ('when-your-faith-feels-far-away', 'When Your Faith Feels Far Away', 'For a stretch when the practice feels empty and you are not sure what is left. It asks for the smallest version rather than the whole thing, the honest words rather than the right ones, and treats dryness as part of a long tradition.', 'Faith', '["Go once without waiting to feel like it — showing up is a practice, not a performance.", "Keep the smallest version of the practice — a minute of it beats an abandoned hour.", "Say the honest thing rather than the right one — a flat prayer is still a prayer.", "Read something old you used to love — your own notes in the margin still carry.", "Tell one person in the community — most of them have had this stretch and said nothing.", "Do one thing for someone quietly — the hands often get there before the heart does.", "Let the doubt be part of it, not the end — dryness has a long history in every tradition.", "Ask what else is tired — grief, work and short sleep all look like this from the inside."]'::jsonb, 'weekly', array['Values', 'Loneliness']::text[], 1, '2026-10-30T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
